    EXPECT_EQ(GenerateTick_Count(), 0UL);
    GenerateTick();
    GenerateTick();
    GenerateTick();
    EXPECT_EQ(GenerateTick_Count(), 3UL);
    GenerateTick_Reset();
    EXPECT_EQ(GenerateTick_Count(), 0UL);
