struct Script {
    std::vector<SensorSamples> steps;
    size_t next = 0;
};

static bool script_source(SensorSamples *out, void *ctx) {
    Script *sc = static_cast<Script *>(ctx);
    if (sc->next >= sc->steps.size()) return false;
    *out = sc->steps[sc->next++];
    return true;
}

