TEST_F(MainFunctional, RunStopsAtTickLimit) {
    Script sc;
    sc.steps.resize(10);
    unsigned long n = RvcMain_Run(spy::port(), script_source, &sc, 3);
    EXPECT_EQ(n, 3UL);
    EXPECT_EQ(sc.next, 3u);
}

